package kr.co.TRSolution.trsIbp.notice.web;import javax.annotation.Resource;import javax.servlet.http.*;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.ModelAndView;import kr.co.TRSolution.trsIbp.notice.service.NoticeService;import kr.co.TRSolution.trsIbp.notice.vo.NoticeVO;import kr.co.TRSolution.trsIbp.user.vo.UserVO;
@Controller public class NoticeController{@Resource(name="noticeService")private NoticeService s;@RequestMapping("/notice/noticeList.do")public String p(){return "/notice/noticeList";}@RequestMapping("/notice/noticeList.ajax")public ModelAndView list(NoticeVO v,HttpServletRequest r){v.setCoId(login(r).getCoId());ModelAndView m=j();m.addObject("list",s.selectNoticeList(v));m.addObject("result","OK");return m;}@RequestMapping("/notice/popupList.ajax")public ModelAndView pop(NoticeVO v,HttpServletRequest r){v.setCoId(login(r).getCoId());ModelAndView m=j();m.addObject("list",s.selectPopupList(v));m.addObject("result","OK");return m;}@RequestMapping("/notice/noticeDetail.ajax")public ModelAndView detail(NoticeVO v,HttpServletRequest r){v.setCoId(login(r).getCoId());ModelAndView m=j();m.addObject("detail",s.selectNotice(v));m.addObject("result","OK");return m;}@RequestMapping(value="/notice/noticeSave.ajax",method=RequestMethod.POST)public ModelAndView save(NoticeVO v,HttpServletRequest r){UserVO u=login(r);v.setCoId(u.getCoId());v.setNoticeScopeCd("COMPANY");v.setRgtrId(u.getUserId());v.setMdfrId(u.getUserId());ModelAndView m=j();try{int changed=s.saveNotice(v);m.addObject("result",changed>0?"OK":"FAIL");if(changed==0)m.addObject("msg","수정 가능한 회사 공지가 아니거나 이미 삭제되었습니다.");}catch(Exception e){m.addObject("result","FAIL");m.addObject("msg",e.getMessage());}return m;}@RequestMapping(value="/notice/noticeDelete.ajax",method=RequestMethod.POST)public ModelAndView del(NoticeVO v,HttpServletRequest r){UserVO u=login(r);v.setCoId(u.getCoId());v.setMdfrId(u.getUserId());ModelAndView m=j();m.addObject("result",s.deleteNotice(v)>0?"OK":"FAIL");return m;}private UserVO login(HttpServletRequest r){UserVO u=(UserVO)r.getSession().getAttribute("login");if(u==null)throw new IllegalStateException("로그인이 필요합니다.");return u;}private ModelAndView j(){return new ModelAndView("jsonView");}}
